window.RP_SESSION={"id":"S-f050c178385a","messages":[{"id":"RP-III-0005298","time":"2026-01-11T20:23:00+09:00","room":"RP III","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"저 먼치에서 길드를 향해 걸어오는 한 데미간. 거대한 덩치에 검을 질질 끌며 오는 그는 헬리오스. 허나 표정은 잔뜩 굳어있는지 오래입니다.\n\n어떤 일이 있더라도 피를 보지 않겠다라는 신념의 그는. 제 롱소드에 피를 줄줄 흘리며 나타났습니다. 어깨에는 추악한 그리폰의 머리를, 주머니에는 수많은 그의 발톱을 지니고서···. 천천히 대장간으로 들어갔습니다.\n\n어쩐지 평소와는 다른 표정. 대장간의 불이 밝게 빛납니다.","characters":["P-d5d1b5a0c634"]},{"id":"RP-III-0005299","time":"2026-01-11T20:24:00+09:00","room":"RP III","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"역겨운 냄새가 가득한 그리폰의 머리를 대강 구석에 던져놓고, 얼굴을 닦은 뒤···. 시끌벅적한 연병장으로 향합니다.","characters":["P-d5d1b5a0c634"]},{"id":"RP-III-0005300","time":"2026-01-11T20:24:00+09:00","room":"RP III","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d5d1b5a0c634"]},{"id":"RP-III-0005301","time":"2026-01-11T20:24:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
